      "For the air handler control only, alert code 114 is generated only if the measured line frequency is below 57Hz or above 63Hz and remains out of range for 10 consecutive seconds. We count power line cycles and determine line frequency every 1 second of time based on the processor's quartz crystal oscillator. We have a fair amount of filtering on when we consider a power line cycle to have occurred, so there would have to be really bad distortion for it to count an extra cycle or miss a real cycle.",
      "Voltage low enough to miss a cycle would generate an alert code 115. There are lots of events, such as power utility substation switching, that could occasionally make our power line frequency off by one count. These are rare one-time events and I don't know anything other than a generator with bad frequency that could cause problems long enough to cause this alert code.",
