      "Ensure there are no connecting wires between multiple indoor units before completing the next step. > The commissioning process must be completed before the system is able to run in normal operation. - MMPD, MMLD MULTI-ZONE condensing models: a. Press the K1 button once to start the auto addressing process. After system has run and stopped itself, \"K1oK\" appears on the display. b. Press the K1 button once more to finalize auto addressing. - MMPD, MMLD Single Zone condensing models: a. Press the K2 button 7 times to display KE on the left display. After system has run and stopped itself, display will read \"PASS\". b. Press the K1 button once to return the system to normal operation. - MWLD, MWPD, MWHD condensing models: a. Use the wireless remote at the indoor unit to complete \"Smart Install Mode\". b. Press the Set, Mode, and Power button simultaneously for 4 seconds. The indoor unit will start counting from 0-99. Once complete the system will return to normal operation.",
